      StringSwitch<std::pair<ELFKind, uint16_t>>(s)
          .Cases({"aarch64elf", "aarch64linux"}, {ELF64LEKind, EM_AARCH64})
          .Cases({"aarch64elfb", "aarch64linuxb"}, {ELF64BEKind, EM_AARCH64})
