633	void LinkerDriver::linkerMain(ArrayRef<const char *> argsArr) {
634	  ELFOptTable parser;
635	  opt::InputArgList args = parser.parse(ctx, argsArr.slice(1));
636	
637	  // Interpret these flags early because Err/Warn depend on them.
638	  ctx.e.errorLimit = args::getInteger(args, OPT_error_limit, 20);
639	  ctx.e.fatalWarnings =
640	      args.hasFlag(OPT_fatal_warnings, OPT_no_fatal_warnings, false) &&
641	      !args.hasArg(OPT_no_warnings);
642	  ctx.e.suppressWarnings = args.hasArg(OPT_no_warnings);
643	
644	  // Handle -help
645	  if (args.hasArg(OPT_help)) {
646	    printHelp(ctx);
647	    return;
648	  }
649	
650	  // Handle -v or -version.
651	  //
652	  // A note about "compatible with GNU linkers" message: this is a hack for
653	  // scripts generated by GNU Libtool up to 2021-10 to recognize LLD as
654	  // a GNU compatible linker. See
655	  // <https://lists.gnu.org/archive/html/libtool/2017-01/msg00007.html>.
656	  //
657	  // This is somewhat ugly hack, but in reality, we had no choice other
658	  // than doing this. Considering the very long release cycle of Libtool,
659	  // it is not easy to improve it to recognize LLD as a GNU compatible
660	  // linker in a timely manner. Even if we can make it, there are still a
